  ('6e2a5c57-72d0-40cd-baf6-cd3b4ead4b1a', 'c25c0ff9-64f8-467a-be35-f5bed964706c', '2026-06-19'::date, E'Morning coffee, quiet house. what does a good apology look like to you... let me thikn. The dog woke me up at 5 and honestly the sunrise was worth it.\n\nI keep replaying a dumb thing I said in a meeting. Nobody else remembers it, I\'m sure. Grateful, I guess.', 'private', '2026-06-20T02:28:00+00:00'::timestamptz, '2026-06-20T02:28:28+00:00'::timestamptz),
  ('73874e70-93f4-453b-9b61-443568f74a87', 'c25c0ff9-64f8-467a-be35-f5bed964706c', '2026-06-21'::date, 'Okay. I used to think being busy meant being important. More tomorrow maybe.', 'private', '2026-06-22T02:44:00+00:00'::timestamptz, '2026-06-22T02:44:17+00:00'::timestamptz)
) as v(id, user_id, d, content, visibility, created_at, updated_at)
